'use strict';

let Js_types = require("@rescript/runtime/lib/js/Js_types.js");
let Primitive_option = require("@rescript/runtime/lib/js/Primitive_option.js");

function makeArrayBuffer(url) {
  let ws = new WebSocket(url);
  ws.binaryType = "arraybuffer";
  return ws;
}

function isOpen(ws) {
  return ws.readyState === WebSocket.OPEN;
}

function messageIsText(message) {
  return Js_types.test(message.data, "String");
}

function messageAsText(message) {
  if (Js_types.test(message.data, "String")) {
    return message.data;
  }
}

function messageAsBinary(message) {
  if (!Js_types.test(message.data, "String")) {
    return Primitive_option.some(message.data);
  }
}

exports.makeArrayBuffer = makeArrayBuffer;
exports.isOpen = isOpen;
exports.messageIsText = messageIsText;
exports.messageAsText = messageAsText;
exports.messageAsBinary = messageAsBinary;
/* No side effect */
